import streamlit as st
import pandas as pd
import base64
import os
import io

# ==========================================
# 1. CONFIGURAÇÃO DE SENHA
# ==========================================
SENHA_ACESSO = "cirurgia123" # Altere para a senha que preferir

def check_password():
    if "password_correct" not in st.session_state:
        st.session_state["password_correct"] = False

    if not st.session_state["password_correct"]:
        st.markdown("### 🔒 Acesso Restrito - Controle de Materiais")
        senha = st.text_input("Digite a senha de acesso", type="password")
        if st.button("Entrar"):
            if senha == SENHA_ACESSO:
                st.session_state["password_correct"] = True
                st.rerun()
            else:
                st.error("Senha incorreta.")
        return False
    return True

if not check_password():
    st.stop()

# ==========================================
# 2. BANCO DE DADOS EMBUTIDO (XLS EXTRAÍDOS)
# ==========================================
# Aqui estão os 94 itens extraídos dos seus arquivos do Flex Lab
B64_CSV = ""

if not os.path.exists("estoque_cirurgico.csv"):
    csv_decoded = base64.b64decode(B64_CSV).decode('utf-8')
    with open("estoque_cirurgico.csv", "w", encoding="utf-8") as f:
        f.write(csv_decoded)

if not os.path.exists("cartoes_pacientes.csv"):
    df_empty = pd.DataFrame(columns=["Paciente", "NIP", "Data", "Pregão", "Materiais Usados", "Anotações Específicas"])
    df_empty.to_csv("cartoes_pacientes.csv", index=False)

df_estoque = pd.read_csv("estoque_cirurgico.csv")
df_cartoes = pd.read_csv("cartoes_pacientes.csv")

# ==========================================
# 3. INTERFACE DA APLICAÇÃO
# ==========================================
st.set_page_config(page_title="Gestão de Materiais Cirúrgicos", layout="wide")
st.title("🏥 Gestão de Materiais Cirúrgicos (Pregões 69/23 e 78/24)")

tab1, tab2, tab3 = st.tabs(["🛒 Nova Cirurgia (Subtração)", "📦 Estoque (Tempo Real)", "📂 Cartões de Pacientes"])

with tab1:
    st.header("Registrar Uso em Cirurgia")
    col1, col2, col3 = st.columns(3)
    with col1: paciente = st.text_input("Nome do Paciente")
    with col2: nip = st.text_input("NIP")
    with col3: data_cirurgia = st.date_input("Data da Cirurgia")
    
    pregao_selecionado = st.selectbox("Selecione o Pregão", sorted(df_estoque['Pregão'].astype(str).unique()))
    
    # Filtrar itens que possuem saldo positivo
    df_filtrado = df_estoque[(df_estoque['Pregão'].astype(str) == pregao_selecionado) & (df_estoque['Quantidade Disponível'] > 0)]
    
    materiais_selecionados = st.multiselect("Selecione os Materiais Utilizados", df_filtrado['Descrição'].tolist())
    
    quantidades_usadas = {}
    if materiais_selecionados:
        st.write("**Quantidades Utilizadas:**")
        for mat in materiais_selecionados:
            qtd_disp = int(df_filtrado[df_filtrado['Descrição'] == mat]['Quantidade Disponível'].values[0])
            qtd = st.number_input(f"{mat} (Disponível: {qtd_disp})", min_value=1, max_value=qtd_disp, step=1, key=mat)
            quantidades_usadas[mat] = qtd
            
    anotacoes = st.text_area("Anotações Específicas sobre a Cirurgia (Em Branco)")
    
    if st.button("Salvar Cartão e Atualizar Estoque", type="primary"):
        if paciente and nip and materiais_selecionados:
            # 1. Atualizar o estoque
            for mat, qtd in quantidades_usadas.items():
                idx = df_estoque.index[(df_estoque['Pregão'].astype(str) == pregao_selecionado) & (df_estoque['Descrição'] == mat)].tolist()[0]
                df_estoque.at[idx, 'Quantidade Disponível'] -= qtd
            df_estoque.to_csv("estoque_cirurgico.csv", index=False)
            
            # 2. Gerar o cartão do paciente
            lista_materiais_str = "\n".join([f"{qtd}x {mat}" for mat, qtd in quantidades_usadas.items()])
            novo_cartao = pd.DataFrame([{
                "Paciente": paciente,
                "NIP": nip,
                "Data": data_cirurgia.strftime("%d/%m/%Y"),
                "Pregão": pregao_selecionado,
                "Materiais Usados": lista_materiais_str,
                "Anotações Específicas": anotacoes
            }])
            df_cartoes = pd.concat([df_cartoes, novo_cartao], ignore_index=True)
            df_cartoes.to_csv("cartoes_pacientes.csv", index=False)
            
            st.success(f"✅ Cartão gerado para {paciente} e estoque atualizado com sucesso!")
            st.balloons()
        else:
            st.warning("⚠️ Preencha o nome do paciente, NIP e selecione pelo menos um material.")

with tab2:
    st.header("Estoque Atualizado")
    st.dataframe(df_estoque, use_container_width=True, hide_index=True)

with tab3:
    st.header("Histórico de Cirurgias (Cartões dos Pacientes)")
    st.dataframe(df_cartoes, use_container_width=True, hide_index=True)